47	        // Tier filtering: skip providers that don't support the current mode
48	        let eligibleProviders = providers.filter { $0.supportedPrivacyTiers.contains(currentMode) }
49	
50	        let sanitizedText = sanitize(text)
51	        var allResults: [KnowledgeResult] = []
52	
53	        await withTaskGroup(of: [KnowledgeResult].self) { group in
