130	/// typed errors (ContextProviderTimeoutError here, TimeoutError there) appropriate
131	/// to their context. Consolidation would require a shared utility module — not
132	/// justified for one 10-line function.
133	private func withTimeout<T: Sendable>(
134	    seconds: Double,
135	    operation: @Sendable @escaping () async throws -> T
136	) async throws -> T {
137	    try await withThrowingTaskGroup(of: T.self) { group in
138	        group.addTask { try await operation() }
139	        group.addTask {
140	            try await Task.sleep(for: .seconds(seconds))
141	            throw ContextProviderTimeoutError()
142	        }
143	        defer { group.cancelAll() }
144	        guard let result = try await group.next() else { throw ContextProviderTimeoutError() }
145	        return result
146	    }
147	}
