import Foundation

/// Capability protocol for reading persisted audio recording metadata.
///
/// Consumed by call sites that only need to look up or list recordings and
/// should not be granted the ability to mutate storage.
public protocol RecordingReadRepository: Sendable {
    /// Fetches a single recording by its unique identifier.
    ///
    /// - Parameter id: The stable, opaque identifier of the recording to retrieve.
    /// - Returns: The ``StoredRecording`` associated with `id`.
    /// - Throws: ``RecordingNotFoundError`` if no recording exists for `id`;
    ///   a storage error for any other persistence failure.
    func getRecording(id: RecordingID) async throws -> StoredRecording

    /// Returns all recordings, sorted by creation date descending (newest first).
    ///
    /// An empty array signals that no recordings exist; this method does not throw
    /// to indicate an empty collection.
    /// - Returns: An array of ``RecordingSummary`` values ordered newest-first,
    ///   or an empty array if no recordings have been saved.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary]

    /// Returns the total disk space consumed by all stored recordings, in bytes.
    ///
    /// Counts only audio files tracked by this repository; temporary files and
    /// WAV debug dumps are excluded.
    /// - Returns: The aggregate file size in bytes (`Int64`).
    /// - Throws: A storage error if the size cannot be computed.
    func totalStorageSize() async throws -> Int64

    /// Returns the IDs of all sessions that were started but never completed (#161 recovery flow).
    ///
    /// A pending session is one where `markSessionStarted(id:startedAt:)` was called
    /// but `saveRecording(_:)` was never called (e.g. the app crashed mid-recording).
    /// Called once at app launch to surface crash-recovery candidates to the user.
    ///
    /// - Returns: An array of ``RecordingID`` values for incomplete sessions, oldest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listPendingSessions() async throws -> [RecordingID]

    /// Returns full metadata for all recordings in a single storage call, sorted
    /// newest-first.
    ///
    /// Prefer this over listRecordings() + N x getRecording(id:) when the caller
    /// needs the complete RecordingMetadata for every recording. One round-trip
    /// to the persistence layer replaces N+1 serial calls.
    ///
    /// - Returns: An array of RecordingMetadata ordered newest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata]

    /// Returns IDs of recordings whose transcription failed and need a retry (#116).
    ///
    /// A recording enters this state when `markNeedsRetranscription(id:audioURL:)` was
    /// called by `StopAndTranscribeUseCase` after a WhisperKit/MLX crash, and has not
    /// yet been successfully re-transcribed.
    ///
    /// - Returns: An array of ``RecordingID`` values for crash-recoverable sessions, oldest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listNeedsRetranscription() async throws -> [RecordingID]
}

public extension RecordingReadRepository {
    /// Convenience overload: full unbounded listing (protocols cannot declare default arguments).
    func listRecordings() async throws -> [RecordingSummary] {
        try await listRecordings(limit: nil, offset: nil)
    }
}
