     ```swift
     import Testing
     import Foundation
     @testable import Presentation
     import Domain

     @Suite("LiveTranscriptionBatching")
     struct LiveTranscriptionBatchingTests {

         @MainActor
         @Test func rapidAppendsAreBatched() async throws {
             let vm = LiveTranscriptionViewModel()
             var callbackCount = 0
             vm.onSegmentsAppended = { _ in callbackCount += 1 }

             // Rapidly append 10 segments (simulating streaming)
             for i in 0 ..< 10 {
                 vm.appendSegment(makeSegment(index: i))
             }

             // Deterministic: await the batch timer itself instead of wall-clock
             // sleeping — sleeps flake under parallel suite load (#307).
             await vm.waitForPendingFlush()

             // With batching, callback should fire fewer than 10 times
             #expect(callbackCount < 10, "Expected batched callbacks but got \(callbackCount) for 10 segments")

             // All segments should still be present and ordered
             #expect(vm.segments.count == 10)
         }

         @MainActor
         @Test func allSegmentsPreservedAfterBatch() async throws {
             let vm = LiveTranscriptionViewModel()

             for i in 0 ..< 5 {
                 vm.appendSegment(makeSegment(index: i))
             }

             await vm.waitForPendingFlush()

             #expect(vm.segments.count == 5)
             for (i, segment) in vm.segments.enumerated() {
                 #expect(segment.timestamp == TimeInterval(i) * 0.1)
             }
         }

         @MainActor
         @Test func timestampOrderingPreservedWithOutOfOrderSegments() async throws {
             let vm = LiveTranscriptionViewModel()

             // Append segments out of timestamp order
             vm.appendSegment(makeSegment(index: 3))
             vm.appendSegment(makeSegment(index: 1))
             vm.appendSegment(makeSegment(index: 4))
             vm.appendSegment(makeSegment(index: 0))
             vm.appendSegment(makeSegment(index: 2))

             await vm.waitForPendingFlush()

             #expect(vm.segments.count == 5)
             // Verify sorted by timestamp. zip never traps on short/empty arrays,
             // unlike `1 ..< count` which crashed the whole run when count == 0 (#307).
             for (earlier, later) in zip(vm.segments, vm.segments.dropFirst()) {
                 #expect(later.timestamp >= earlier.timestamp)
             }
         }

         @MainActor
         @Test func clearCancelsPendingBatch() async throws {
             let vm = LiveTranscriptionViewModel()
             var callbackCount = 0
             vm.onSegmentsAppended = { _ in callbackCount += 1 }

             for i in 0 ..< 5 {
                 vm.appendSegment(makeSegment(index: i))
             }

             // Clear before batch can flush; clear() cancels and drops the timer,
             // so this wait returns immediately — kept to assert post-quiescence state.
             vm.clear()
             await vm.waitForPendingFlush()

             #expect(vm.segments.isEmpty)
             #expect(callbackCount == 0, "Expected no callbacks after clear but got \(callbackCount)")
         }
     }

     private func makeSegment(index: Int) -> StreamingSegment {
         StreamingSegment(
             text: "Segment \(index)",
             isFinal: true,
             track: .system,
             timestamp: TimeInterval(index) * 0.1,
         )
     }
     ```
