=== CPF DiarizationEngine protocol ===
/// Abstracts the speaker diarization backend so the domain layer has no
/// compile-time dependency on any specific embedding or clustering framework.
///
/// Conforming types are expected to be actors or otherwise internally
/// thread-safe; the `Sendable` requirement enforces that instances can cross
/// concurrency boundaries without data races under Swift strict concurrency.
public protocol DiarizationEngine: Sendable {
    // MARK: - Lifecycle

    /// Loads and prepares any models or resources required for diarization.
    ///
    /// Must be called before ``diarize(samples:sampleRate:)``.
    /// Implementations should be idempotent: calling this when resources are
    /// already loaded is a no-op.
    ///
    /// - Throws: A domain error if required resources cannot be loaded.
    func prepare() async throws

    // MARK: - Inference

    /// Identifies speaker boundaries in a buffer of PCM audio samples.
    ///
    /// - Parameters:
    ///   - samples: Mono, 32-bit float PCM samples.
    ///   - sampleRate: The sample rate of `samples` in Hz (e.g. 16 000).
    /// - Returns: An array of ``SpeakerSegment`` values, ordered by start time,
    ///   each describing a contiguous region attributed to a single speaker.
    /// - Throws: A domain error if diarization fails or the engine is not ready.
    func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment]

    // MARK: - Status

    /// Returns `true` when the engine has completed preparation and is ready to
    /// accept calls to ``diarize(samples:sampleRate:)``.
    func isReady() async -> Bool
}

=== CPF SummarizationEngine protocol ===
/// Abstracts the meeting summarisation backend (e.g. MLX LLM) so the domain
/// layer has no compile-time dependency on any inference framework.
public protocol SummarizationEngine: Sendable {
    /// Loads the model described by `config` and prepares it for inference.
    /// - Throws: ``SummarizationError`` if the model cannot be loaded.
    func loadModel(_ config: SummaryConfig) async throws

    /// Generates a structured meeting summary from transcript text, speaker list,
    /// and meeting type (which selects the prompt template).
    func summarize(
        transcript: String, speakers: [String], meetingType: MeetingType
    ) async throws -> MeetingSummary

    /// Returns `true` when the model is loaded and ready for inference.
    func isReady() async -> Bool

    /// Generates text from a raw prompt, bypassing summarization formatting.
    func generate(prompt: String) async throws -> String
}

public extension SummarizationEngine {
    func summarize(transcript: String, speakers: [String]) async throws -> MeetingSummary {
        try await summarize(
            transcript: transcript, speakers: speakers,
            meetingType: SummaryConfig.default.meetingType
        )
    }
}

