import Foundation

/// Errors that can occur during speech transcription.
public enum TranscriptionError: Error, Sendable, UserFacingError {
    /// The transcription model has not been loaded before inference was attempted.
    case modelNotLoaded(underlying: (any Error & Sendable)?)

    /// The inference engine encountered a failure during transcription.
    case inferenceFailed(underlying: (any Error & Sendable)?)

    /// The audio clip is too short to produce a meaningful transcription.
    case audioTooShort

    /// The transcription operation exceeded the allowed time budget.
    case timeout(duration: TimeInterval)

    /// The Apple Neural Engine failed to compile the model.
    case aneCompilationFailed

    /// No cached model was found on disk and the network fetch to download one
    /// failed (#325). Distinct from `.modelNotLoaded` so callers can surface a
    /// "download required" prompt instead of a generic load-failure message.
    case downloadRequired(underlying: (any Error & Sendable)?)

    // MARK: - UserFacingError

    public var userMessage: String {
        switch self {
        case .modelNotLoaded:
            "Transcription model is not loaded yet. Please wait a moment and try again."
        case .inferenceFailed:
            "Transcription failed. Please check your audio and try again."
        case .audioTooShort:
            "Audio is too short to transcribe. Record at least a few seconds."
        case .timeout:
            "Transcription took too long. Try a shorter recording."
        case .aneCompilationFailed:
            "Neural engine compilation failed. Falling back to CPU."
        case .downloadRequired:
            "This model needs to be downloaded before it can be used. Please connect to the internet and try again."
        }
    }

    public var debugDescription: String {
        switch self {
